1	/**
2	 * The fleet loop: one application at a time, each scored by the out-of-band
3	 * harness, each filed where the coverage report reads it.
4	 *
5	 * Three constraints shape everything below, and each of them is a finding this
6	 * repository already paid for:
7	 *
8	 * **The fleet is never in source.** A batch that lists its applications in a
9	 * TypeScript array is not a fleet tool; it is a fixture wearing one. The list
10	 * arrives as `--apps <manifest>` or as repeated `--apps <root>` values, and this
11	 * module has no default list to fall back to.
12	 *
13	 * **A refusal is a returned outcome, not an exception to catch.** The harness
14	 * reports the terminal classification the run reached — `refused:<code>` when a
15	 * stage declined — and this loop reads it. Nothing here infers a refusal from a
16	 * thrown stack. A `try` remains around each invocation for exactly one reason:
17	 * an application whose harness *broke* is one `defect:*` row, not a batch that
18	 * stops at application three of three hundred.
19	 *
20	 * **The loop is serial.** The witness serializes per host, and determinism under
21	 * load is the property being protected; a fleet that fans out gets faster
22	 * numbers and loses the reading they were for. Operator stages may fan out
23	 * later. This loop does not.
24	 *
25	 * What the batch produces is a summary, and the summary is the product: totals
26	 * that never restate a bounded per-app outcome more generally, refused rows
27	 * carrying their named code and their message verbatim, and a terminal pass
28	 * through the enterprise honesty guard before anything is written.
29	 */
30	
31	import { execFile } from 'node:child_process';
32	import { mkdir, readFile, readdir, stat, writeFile } from 'node:fs/promises';
33	import * as path from 'pathe';
34	import {
35		ANGULAR_PRE_IVY_BOUNDARY_POPULATION_STATEMENT,
36		ANGULAR_PRE_IVY_BOUNDARY_PREVALENCE,
37	} from '../../../core/src/receipts/angular-pre-ivy-boundary-amendment.ts';
38	import { HOLDOUT_ANGULAR_ESHOP_WEBSPA_OUTCOME } from '../../../core/src/receipts/holdout-angular-eshop-webspa.ts';
39	import { assertEnterpriseSurfaceHonesty } from '../../../trust/src/enterprise.ts';
40	import { acquisitionLaneOf } from './ingest.ts';
41	import { INTERVENTION_COUNT_SCHEMA, interventionRecordPathFor } from './intervention-count.ts';
42	import { refuse } from './refusals.ts';
43	import { displayPath, writeRecord } from './record.ts';
44	
45	export const FLEET_BATCH_SCHEMA = 'versionless.fleet-batch.v1';
46	
47	/** Where a fleet summary is filed, one directory per batch. */
48	export const FLEET_BATCH_ROOT = 'evidence/runs/fleet-batch';
49	export const FLEET_SUMMARY_JSON = 'fleet-summary.json';
50	export const FLEET_SUMMARY_MARKDOWN = 'fleet-summary.md';
51	
52	/** Where each application's run record is filed, so the coverage report reads it. */
53	export const RUN_RECORD_ROOT = 'evidence/runs';
54	export const RUN_RECORD_FILE = 'run-record.json';
55	
56	/**
57	 * What a batch establishes and what it does not.
58	 *
59	 * The first, third and fourth entries are carried verbatim from the batch
60	 * operator dry run that measured this loop's machine time; they were true of
61	 * that spike and remain true of this command. The rest are this command's own.
62	 */
63	export const FLEET_NOT_ESTABLISHED: readonly string[] = Object.freeze([
64		'A count of refusal sites is not a count of refusable applications. What this summary tallies is the outcome each named application reached on this host, in this order, once.',
65		'A refusal is an outcome rather than a failure of the run. The refusing roots are counted at the cost they actually took.',
66		'The fleet here is whatever list this command was handed. It is not a random sample of any target fleet and it carries whatever selection that list carries.',
67		'The timings are one host, one process, a warm page cache and one repetition. They are a reading of this machine rather than a specification.',
68		'An intervention count of zero is the out-of-band harness reporting that no path outside the declared write set changed and that one process was spawned. It is not a statement that any application in this batch produced a working build.',
69		'Applications ran one at a time. Nothing here establishes what any of these outcomes would have been under a loop that fanned out, and the witness surface is the reason this one does not.',
70		'The publish steps below, when declared, report what each command exited with. A regenerated report is a re-derivation of what the evidence on disk already carried; it is not certification, and no authenticity claim rides along with it.',
71	]);
72	
73	export type BatchApplication = Readonly<{
74		id: string;
75		root: string;
76		framework?: string;
77	}>;
78	
79	export type BatchRow = Readonly<{
80		id: string;
81		framework: string;
82		applicationRoot: string;
83		lane: string;
84		terminalClassification: string;
85		interventionCount: number | null;
86		exitCode: number | null;
87		/**
88		 * The refusal the run record carries, verbatim: the code, the message, and
89		 * the stage that raised it. The stage is the third field of the same
90		 * refusal, and a summary that reports which code fired without reporting
91		 * where it fired cannot say how far an application got.
92		 */
93		refusal: Readonly<{ code: string; message: string; stage: string }> | null;
94		elapsedMs: number;
95		runRecordPath: string;
96		interventionRecordPath: string;
97		detail?: string;
98	}>;
99	
100	export type PublishStep = Readonly<{
101		step: string;
102		command: string;
103		argv: readonly string[];
104		env?: Readonly<Record<string, string>>;
105		/** Why a step may be skipped, when the condition it depends on is not met. */
106		condition?: string;
107	}>;
108	
109	export type PublishStepOutcome = Readonly<{
110		step: string;
111		command: string;
112		status: 'ran' | 'skipped' | 'failed' | 'not-run';
113		exitCode: number | null;
114		detail: string;
115	}>;
116	
117	export type PublishExecution = Readonly<{
118		exitCode: number | null;
119		stdout: string;
120		stderr: string;
121	}>;
122	
123	export type PublishExecutor = (step: PublishStep) => Promise<PublishExecution>;
124	
125	export type HarnessInvocation = Readonly<{
126		id: string;
127		applicationRoot: string;
128		lane: string;
129		runRecord: string;
130		/** The operator arguments, exactly as a shell operator would type them. */
131		argv: readonly string[];
132	}>;
133	
134	export type HarnessOutcome = Readonly<{ text: string; json: unknown; exitCode: number }>;
135	export type HarnessRunner = (invocation: HarnessInvocation) => Promise<HarnessOutcome>;
136	
137	export type BatchDeclarations = Readonly<{
138		applications: readonly BatchApplication[];
139		laneRoot: string;
140		/** The declarations forwarded to every application's harness, unchanged. */
141		forwarded: readonly string[];
142		name: string;
143		publish: boolean;
144		root: string;
145		appsSource: readonly string[];
146	}>;
147	
148	export type FleetSummary = Readonly<{
149		schemaVersion: typeof FLEET_BATCH_SCHEMA;
150		flow: 'batch';
151		name: string;
152		startedAt: string;
153		endedAt: string;
154		machineTimeMs: number;
155		declared: Readonly<{
156			applicationsFrom: readonly string[];
157			laneRoot: string;
158			forwarded: readonly string[];
159			concurrency: string;
160			publish: string;
161		}>;
162		totals: Readonly<{
163			applications: number;
164			proven: number;
165			refused: number;
166			refusedByCode: Readonly<Record<string, number>>;
167			defects: number;
168			interventionCount: number;
169			interventionCountNotAsserted: number;
170		}>;
171		unattended: Readonly<{ state: boolean; statement: string }>;
172		applications: readonly BatchRow[];
173		publish: Readonly<{ declared: boolean; steps: readonly PublishStepOutcome[] }>;
174		notEstablished: readonly string[];
175	}>;
176	
177	/**
178	 * The identity of an application root, inferred the way ingest infers it.
179	 *
180	 * An acquired tree sits at `.versionless/work/<id>/baseline`, and that `<id>` is
181	 * the name the pipeline already files evidence under. A root that is not a lane
182	 * baseline yields its own directory name, which is a name for this batch rather
183	 * than a claim about the application's declared identity.
184	 */
185	export function inferApplicationId(root: string): string {
186		const lane = acquisitionLaneOf(root);
187		if (lane !== null) return lane.laneId;
188		const base = path.basename(path.resolve(root));
189		return base === '' ? 'application' : base;
190	}
191	
192	/**
193	 * Read the fleet list from a manifest, or take an entry as one application root.
194	 *
195	 * Two manifest shapes are read because two are already written by hand: a JSON
196	 * document carrying `applications`, and a newline list of roots. Neither is a
197	 * list this module carries — an entry that names no readable list and no
198	 * readable directory is refused rather than dropped.
199	 */
200	export function parseManifest(body: string, source: string): readonly BatchApplication[] {
201		const trimmed = body.trim();
202		if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
203			let parsed: unknown;
204			try {
205				parsed = JSON.parse(trimmed);
206			} catch {
207				refuse({
208					code: 'batch.manifest-is-not-readable',
209					message: `batch: ${source} is not readable as JSON. A manifest is a JSON document carrying \`applications\`, or a newline list of application roots.`,
210					stage: 'batch',
211					origin: 'pipeline',
212				});
213			}
214			const entries = Array.isArray(parsed)
215				? parsed
216				: ((parsed as { applications?: unknown }).applications ?? null);
217			if (!Array.isArray(entries))
218				refuse({
219					code: 'batch.manifest-declares-no-applications',
220					message: `batch: ${source} carries no \`applications\` array. This command has no fleet of its own to fall back to.`,
221					stage: 'batch',
222					origin: 'pipeline',
223				});
224			return Object.freeze(
225				(entries as readonly unknown[]).map((entry) => {
226					if (typeof entry === 'string')
227						return Object.freeze({ id: inferApplicationId(entry), root: entry });
228					const record = (entry ?? {}) as Record<string, unknown>;
229					const root = typeof record.root === 'string' ? record.root : null;
230					if (root === null)
231						refuse({
232							code: 'batch.manifest-entry-names-no-root',
233							message: `batch: an entry in ${source} names no \`root\`. Every application in a manifest is a root this command can read.`,
234							stage: 'batch',
235							origin: 'pipeline',
236						});
237					return Object.freeze({
238						id:
239							typeof record.id === 'string'
240								? record.id
241								: inferApplicationId(root as string),
242						root: root as string,
243						...(typeof record.framework === 'string'
244							? { framework: record.framework }
245							: {}),
246					});
247				}),
248			);
249		}
250		const roots = trimmed
251			.split('\n')
252			.map((line) => line.trim())
253			.filter((line) => line !== '' && !line.startsWith('#'));
254		if (roots.length === 0)
255			refuse({
256				code: 'batch.manifest-declares-no-applications',
257				message: `batch: ${source} lists no application roots. This command has no fleet of its own to fall back to.`,
258				stage: 'batch',
259				origin: 'pipeline',
260			});
261		return Object.freeze(
262			roots.map((root) => Object.freeze({ id: inferApplicationId(root), root })),
263		);
264	}
265	
266	async function isFile(target: string): Promise<boolean> {
267		try {
268			return (await stat(target)).isFile();
269		} catch {
270			return false;
271		}
272	}
273	
274	async function isDirectory(target: string): Promise<boolean> {
275		try {
276			return (await stat(target)).isDirectory();
277		} catch {
278			return false;
279		}
280	}
281	
282	/** The fleet, in the order it was declared, from files and roots and nowhere else. */
283	export async function readFleet(entries: readonly string[]): Promise<readonly BatchApplication[]> {
284		if (entries.length === 0)
285			refuse({
286				code: 'batch.no-applications-declared',
287				message:
288					'batch: --apps <manifest-file> or --apps <application-root> is required, and may be repeated. This command carries no fleet in its own source.',
289				stage: 'batch',
290				origin: 'pipeline',
291			});
292		const applications: BatchApplication[] = [];
293		for (const entry of entries) {
294			if (await isFile(entry)) {
295				applications.push(...parseManifest(await readFile(entry, 'utf8'), displayPath(entry)));
296				continue;
297			}
298			if (await isDirectory(entry)) {
299				applications.push(Object.freeze({ id: inferApplicationId(entry), root: entry }));
300				continue;
301			}
302			refuse({
303				code: 'batch.declared-application-is-not-readable',
304				message: `batch: ${entry} is neither a manifest file nor a directory this command can read. A fleet entry names something on disk.`,
305				stage: 'batch',
306				origin: 'pipeline',
307			});
308		}
309		return Object.freeze(applications);
310	}
311	
312	/** The operator arguments the harness is invoked with, for one application. */
313	export function harnessInvocationFor(
314		application: BatchApplication,
315		declarations: Pick<BatchDeclarations, 'laneRoot' | 'forwarded'>,
316	): HarnessInvocation {
317		const lane = path.join(declarations.laneRoot, application.id);
318		const runRecord = path.join(RUN_RECORD_ROOT, application.id, RUN_RECORD_FILE);
319		return Object.freeze({
320			id: application.id,
321			applicationRoot: application.root,
322			lane,
323			runRecord,
324			argv: Object.freeze([
325				application.root,
326				'--out',
327				lane,
328				'--record',
329				runRecord,
330				'--json',
331				...declarations.forwarded,
332			]),
333		});
334	}
335	
336	type RunReading = Readonly<{
337		refusal?: { code?: unknown; message?: unknown; stage?: unknown };
338		lineage?: unknown;
339	}>;
340	
341	async function readRunRecord(file: string): Promise<RunReading | null> {
342		try {
343			const parsed: unknown = JSON.parse(await readFile(path.resolve(file), 'utf8'));
344			return typeof parsed === 'object' && parsed !== null ? (parsed as RunReading) : null;
345		} catch {
346			return null;
347		}
348	}
349	
350	/**
351	 * One application: invoke the harness, read what it returned, build the row.
352	 *
353	 * The classification comes off the harness record verbatim. The refusal code and
354	 * message come off the run record the harness scored, also verbatim — a fleet
355	 * report that paraphrases why an application declined is a fleet report an
356	 * operator cannot act on.
357	 */
358	export async function runOneApplication(
359		application: BatchApplication,
360		declarations: Pick<BatchDeclarations, 'laneRoot' | 'forwarded'>,
361		runHarness: HarnessRunner,
362	): Promise<BatchRow> {
363		const invocation = harnessInvocationFor(application, declarations);
364		const started = Date.now();
365		const base = {
366			id: application.id,
367			framework: application.framework ?? 'not-recorded',
368			applicationRoot: displayPath(application.root),
369			lane: displayPath(invocation.lane),
370			runRecordPath: invocation.runRecord,
371			interventionRecordPath: interventionRecordPathFor(invocation.runRecord),
372		};
373		let outcome: HarnessOutcome;
374		try {
375			outcome = await runHarness(invocation);
376		} catch (error) {
377			/**
378			 * The harness broke. That is one defect row and the loop continues: a
379			 * fleet run that stops at the first broken application reports nothing
380			 * about the applications after it.
381			 */
382			return Object.freeze({
383				...base,
384				terminalClassification: 'defect:harness-did-not-return',
385				interventionCount: null,
386				exitCode: null,
387				refusal: null,
388				elapsedMs: Date.now() - started,
389				detail: error instanceof Error ? error.message : String(error),
390			});
391		}
392		const elapsedMs = Date.now() - started;
393		const record = (outcome.json ?? {}) as Record<string, unknown>;
394		if (record.schemaVersion !== INTERVENTION_COUNT_SCHEMA) {
395			/**
396			 * The harness returned something that is not a count record. That is the
397			 * harness itself refusing — an argument it would not accept, say — and it
398			 * is reported with its named code and no invented count: an unmeasured
399			 * intervention count is not a measured zero.
400			 */
401			const refusal =
402				typeof record.refusal === 'object' && record.refusal !== null
403					? (record.refusal as { code?: unknown; message?: unknown; stage?: unknown })
404					: null;
405			const code = refusal === null ? 'unnamed' : String(refusal.code ?? 'unnamed');
406			return Object.freeze({
407				...base,
408				terminalClassification:
409					outcome.exitCode === 2 ? `refused:${code}` : 'defect:no-harness-record',
410				interventionCount: null,
411				exitCode: outcome.exitCode,
412				refusal:
413					refusal === null
414						? null
415						: Object.freeze({
416								code,
417								message: String(refusal.message ?? ''),
418								stage: String(refusal.stage ?? 'not-recorded'),
419							}),
420				elapsedMs,
421			});
422		}
423		const classification = String(record.terminalClassification ?? 'defect:outcome-not-classified');
424		const reading = classification.startsWith('refused:')
425			? await readRunRecord(invocation.runRecord)
426			: null;
427		const declared = reading?.refusal ?? null;
428		return Object.freeze({
429			...base,
430			framework:
431				application.framework ??
432				(typeof reading?.lineage === 'string' ? reading.lineage : 'not-recorded'),
433			terminalClassification: classification,
434			interventionCount:
435				typeof record.interventionCount === 'number' ? record.interventionCount : null,
436			exitCode: typeof record.exitCode === 'number' ? record.exitCode : null,
437			refusal:
438				declared === null
439					? classification.startsWith('refused:')
440						? Object.freeze({
441								code: classification.slice('refused:'.length),
442								message:
443									'the run record carries no refusal message this batch could read',
444								stage: 'not-recorded',
445							})
446						: null
447					: Object.freeze({
448							code: String(declared.code ?? ''),
449							message: String(declared.message ?? ''),
450							stage: String(declared.stage ?? 'not-recorded'),
451						}),
452			elapsedMs,
453		});
454	}
455	
456	/** The four publish steps, in the one order that leaves a readable report. */
457	export function publishStepsFor(
458		options: Readonly<{ distStale: boolean; trustDir: string; cliEntry: string }>,
459	): readonly PublishStep[] {
460		return Object.freeze([
461			Object.freeze({
462				step: 'pack',
463				command: 'pnpm exec vp pack',
464				argv: Object.freeze(['exec', 'vp', 'pack']),
465				condition: options.distStale
466					? 'packages/cli/dist is older than the sources it is built from'
467					: 'packages/cli/dist is not older than the sources it is built from',
468			}),
469			Object.freeze({
470				step: 'trust:generate',
471				command:
472					'npm run trust:generate -- --offline --policy trust/policy.json --output evidence/trust/current',
473				argv: Object.freeze([
474					'run',
475					'trust:generate',
476					'--',
477					'--offline',
478					'--policy',
479					'trust/policy.json',
480					'--output',
481					options.trustDir,
482				]),
483				env: Object.freeze({ VERSIONLESS_NETWORK_MODE: 'offline' }),
484			}),
485			Object.freeze({
486				step: 'trust:verify',
487				command: 'npm run trust:verify -- --offline',
488				argv: Object.freeze(['run', 'trust:verify', '--', '--offline']),
489				env: Object.freeze({ VERSIONLESS_NETWORK_MODE: 'offline' }),
490			}),
491			Object.freeze({
492				step: 'report:coverage',
493				command: 'report:coverage --offline --verify-only',
494				argv: Object.freeze([
495					'--experimental-strip-types',
496					options.cliEntry,
497					'report:coverage',
498					'--offline',
499					'--verify-only',
500				]),
501				env: Object.freeze({ VERSIONLESS_NETWORK_MODE: 'offline' }),
502			}),
503		]);
504	}
505	
506	/**
507	 * Run the publish chain in order and stop at the first step that did not exit 0.
508	 *
509	 * A chain that carried on past a failed generate would verify the artifacts the
510	 * failed step did not write, so the steps after a failure are recorded
511	 * `not-run` rather than attempted.
512	 */
513	export async function runPublishChain(
514		steps: readonly PublishStep[],
515		execute: PublishExecutor,
516		skip: (step: PublishStep) => boolean = (step) =>
517			step.step === 'pack' &&
518			step.condition?.startsWith('packages/cli/dist is not older') === true,
519	): Promise<readonly PublishStepOutcome[]> {
520		const outcomes: PublishStepOutcome[] = [];
521		let stopped = false;
522		for (const step of steps) {
523			if (stopped) {
524				outcomes.push(
525					Object.freeze({
526						step: step.step,
527						command: step.command,
528						status: 'not-run' as const,
529						exitCode: null,
530						detail: 'an earlier step in this chain did not exit 0, so this step was not run',
531					}),
532				);
533				continue;
534			}
535			if (skip(step)) {
536				outcomes.push(
537					Object.freeze({
538						step: step.step,
539						command: step.command,
540						status: 'skipped' as const,
541						exitCode: null,
542						detail: step.condition ?? 'the condition this step depends on was not met',
543					}),
544				);
545				continue;
546			}
547			let execution: PublishExecution;
548			try {
549				execution = await execute(step);
550			} catch (error) {
551				execution = {
552					exitCode: 1,
553					stdout: '',
554					stderr: error instanceof Error ? error.message : String(error),
555				};
556			}
557			const ran = execution.exitCode === 0;
558			if (!ran) stopped = true;
559			outcomes.push(
560				Object.freeze({
561					step: step.step,
562					command: step.command,
563					status: ran ? ('ran' as const) : ('failed' as const),
564					exitCode: execution.exitCode,
565					detail: ran
566						? (step.condition ?? 'the step exited 0')
567						: execution.stderr.trim().split('\n').slice(-1).join('') ||
568							'the step did not exit 0',
569				}),
570			);
571		}
572		return Object.freeze(outcomes);
573	}
574	
575	/** Spawn a publish step as a child process, with no shell between. */
576	export const spawnPublishStep =
577		(root: string): PublishExecutor =>
578		async (step) =>
579			await new Promise<PublishExecution>((resolve) => {
580				const runtime = step.step === 'report:coverage' ? process.execPath : 'npm';
581				const argv = [...step.argv];
582				const binary = step.step === 'pack' ? 'pnpm' : runtime;
583				execFile(
584					binary,
585					argv,
586					{
587						cwd: root,
588						env: { ...process.env, ...(step.env ?? {}) },
589						maxBuffer: 64 * 1024 * 1024,
590					},
591					(error, stdout, stderr) => {
592						resolve({
593							exitCode:
594								error === null
595									? 0
596									: typeof (error as { code?: unknown }).code === 'number'
597										? ((error as { code?: number }).code ?? 1)
598										: 1,
599							stdout: String(stdout),
600							stderr: String(stderr),
601						});
602					},
603				);
604			});
605	
606	async function newestMtime(root: string, into: { value: number }): Promise<void> {
607		let entries;
608		try {
609			entries = await readdir(root, { withFileTypes: true });
610		} catch {
611			return;
612		}
613		for (const entry of entries) {
614			if (entry.name === 'node_modules' || entry.name === '.git') continue;
615			const full = path.join(root, entry.name);
616			if (entry.isDirectory()) {
617				await newestMtime(full, into);
618				continue;
619			}
620			try {
621				const stats = await stat(full);
622				if (stats.mtimeMs > into.value) into.value = stats.mtimeMs;
623			} catch {
624				/* a file that vanished between the walk and the stat is not a reading */
625			}
626		}
627	}
628	
629	/**
630	 * Whether the built CLI is older than the sources it is built from.
631	 *
632	 * A missing `dist` is stale by construction: there is nothing there that could
633	 * be newer than anything.
634	 */
635	export async function distIsStale(root: string): Promise<boolean> {
636		const dist = { value: 0 };
637		await newestMtime(path.join(root, 'packages/cli/dist'), dist);
638		if (dist.value === 0) return true;
639		const source = { value: 0 };
640		for (const directory of ['packages/cli/src', 'packages/core/src', 'packages/trust/src'])
641			await newestMtime(path.join(root, directory), source);
642		return source.value > dist.value;
643	}
644	
645	function tallyTotals(rows: readonly BatchRow[]): FleetSummary['totals'] {
646		const refusedByCode: Record<string, number> = {};
647		let refused = 0;
648		let proven = 0;
649		let defects = 0;
650		let interventionCount = 0;
651		let notAsserted = 0;
652		for (const row of rows) {
653			if (row.terminalClassification === 'proven') proven += 1;
654			if (row.terminalClassification.startsWith('refused:')) {
655				refused += 1;
656				const code = row.refusal?.code ?? row.terminalClassification.slice('refused:'.length);
657				refusedByCode[code] = (refusedByCode[code] ?? 0) + 1;
658			}
659			if (row.terminalClassification.startsWith('defect:')) defects += 1;
660			if (typeof row.interventionCount === 'number') interventionCount += row.interventionCount;
661			else notAsserted += 1;
662		}
663		return Object.freeze({
664			applications: rows.length,
665			proven,
666			refused,
667			refusedByCode: Object.freeze(refusedByCode),
668			defects,
669			interventionCount,
670			interventionCountNotAsserted: notAsserted,
671		});
672	}
673	
674	/**
675	 * Whether this batch may be described as unattended, and the sentence that says
676	 * so either way.
677	 *
678	 * Three conditions, all of them mechanical: no defect row, an intervention sum
679	 * of zero, and every application having asserted a count. A batch missing any
680	 * of them gets the sentence naming which.
681	 */
682	export function unattendedStatement(totals: FleetSummary['totals']): FleetSummary['unattended'] {
683		const reasons: string[] = [];
684		if (totals.defects > 0)
685			reasons.push(`${String(totals.defects)} application(s) reached a defect classification`);
686		if (totals.interventionCount > 0)
687			reasons.push(
688				`the out-of-band harness observed ${String(totals.interventionCount)} intervention(s)`,
689			);
690		if (totals.interventionCountNotAsserted > 0)
691			reasons.push(
692				`${String(totals.interventionCountNotAsserted)} application(s) asserted no intervention count, and an unmeasured count is not a measured zero`,
693			);
694		if (reasons.length > 0)
695			return Object.freeze({
696				state: false,
697				statement: `This batch is not described as unattended: ${reasons.join('; ')}.`,
698			});
699		return Object.freeze({
700			state: true,
701			statement: `Across ${String(totals.applications)} application(s) the out-of-band harness observed zero interventions and no defect classification. That is a statement about what changed on disk and how many processes were spawned; it is not a statement that any of these applications built or rendered.`,
702		});
703	}
704	
705	/**
706	 * The summary as a document, and the guard the document has to survive.
707	 *
708	 * The boundary statements below are quoted from the receipts that own them
709	 * rather than restated, because the guard this render terminates in is exactly
710	 * the mechanism that refuses a restatement.
711	 */
712	export function renderFleetSummary(summary: FleetSummary): string {
713		const lines: string[] = [];
714		lines.push('# Versionless fleet batch');
715		lines.push('');
716		lines.push(`batch: ${summary.name}`);
717		lines.push(`started: ${summary.startedAt}`);
718		lines.push(`ended: ${summary.endedAt}`);
719		lines.push(`machine time: ${String(summary.machineTimeMs)} ms`);
720		lines.push(`applications declared from: ${summary.declared.applicationsFrom.join(', ')}`);
721		lines.push(`lane root: ${summary.declared.laneRoot}`);
722		lines.push(`forwarded declarations: ${summary.declared.forwarded.join(' ') || 'none'}`);
723		lines.push(`concurrency: ${summary.declared.concurrency}`);
724		lines.push(`publish: ${summary.declared.publish}`);
725		lines.push('');
726		lines.push('## Totals');
727		lines.push('');
728		lines.push(`- applications: ${String(summary.totals.applications)}`);
729		lines.push(`- proven: ${String(summary.totals.proven)}`);
730		lines.push(`- refused: ${String(summary.totals.refused)}`);
731		for (const code of Object.keys(summary.totals.refusedByCode).sort())
732			lines.push(`  - \`${code}\`: ${String(summary.totals.refusedByCode[code])}`);
733		lines.push(`- defects: ${String(summary.totals.defects)}`);
734		lines.push(`- intervention count, summed: ${String(summary.totals.interventionCount)}`);
735		lines.push(
736			`- applications asserting no intervention count: ${String(summary.totals.interventionCountNotAsserted)}`,
737		);
738		lines.push('');
739		lines.push(summary.unattended.statement);
740		lines.push('');
741		lines.push('## Applications');
742		lines.push('');
743		for (const row of summary.applications) {
744			lines.push(`### ${row.id}`);
745			lines.push('');
746			lines.push(`- framework: ${row.framework}`);
747			lines.push(`- application root: \`${row.applicationRoot}\``);
748			lines.push(`- lane: \`${row.lane}\``);
749			lines.push(`- terminal classification: \`${row.terminalClassification}\``);
750			lines.push(
751				`- intervention count: ${row.interventionCount === null ? 'not asserted' : String(row.interventionCount)}`,
752			);
753			lines.push(`- exit code: ${row.exitCode === null ? 'not recorded' : String(row.exitCode)}`);
754			lines.push(`- elapsed: ${String(row.elapsedMs)} ms`);
755			lines.push(`- run record: \`${row.runRecordPath}\``);
756			lines.push(`- harness record: \`${row.interventionRecordPath}\``);
757			if (row.refusal !== null) {
758				lines.push(
759					`- refusal code: \`${row.refusal.code}\` (raised at stage \`${row.refusal.stage}\`)`,
760				);
761				lines.push(`- refusal message: ${row.refusal.message}`);
762			}
763			if (row.detail !== undefined) lines.push(`- detail: ${row.detail}`);
764			lines.push('');
765		}
766		lines.push('## Publish');
767		lines.push('');
768		if (!summary.publish.declared) lines.push('publish: not-declared');
769		for (const step of summary.publish.steps)
770			lines.push(
771				`- \`${step.step}\` — ${step.status} (exit ${step.exitCode === null ? 'not-recorded' : String(step.exitCode)}): ${step.detail}`,
772			);
773		lines.push('');
774		lines.push('## Boundaries this summary does not restate');
775		lines.push('');
776		lines.push(`- ${HOLDOUT_ANGULAR_ESHOP_WEBSPA_OUTCOME}`);
777		lines.push(
778			`- boundary prevalence published as ${ANGULAR_PRE_IVY_BOUNDARY_PREVALENCE.published}`,
779		);
780		lines.push(`- ${ANGULAR_PRE_IVY_BOUNDARY_PREVALENCE.statement}`);
781		lines.push(`- ${ANGULAR_PRE_IVY_BOUNDARY_POPULATION_STATEMENT}`);
782		lines.push(
783			'- The holdout applications named above are counted in no lineage numerator, and no outcome in this batch changes that.',
784		);
785		lines.push('');
786		lines.push('## Not established');
787		lines.push('');
788		for (const entry of summary.notEstablished) lines.push(`- ${entry}`);
789		lines.push('');
790		lines.push(
791			'This document is not certification. It reports what each named application reached on this host, once, in the order declared.',
792		);
793		return `${lines.join('\n')}\n`;
794	}
795	
796	/**
797	 * Every string this summary carries, through the enterprise honesty guard.
798	 *
799	 * The document is checked, and so is the record: a refusal message quoted into
800	 * the JSON but not into the Markdown would otherwise reach a reader unguarded.
801	 */
802	export function assertFleetSummaryHonesty(summary: FleetSummary, markdown: string): void {
803		assertEnterpriseSurfaceHonesty(markdown, 'fleet-batch summary document');
804		const preamble = markdown.split('## Boundaries this summary does not restate')[1] ?? '';
805		assertEnterpriseSurfaceHonesty(
806			`${JSON.stringify(summary, null, '\t')}\n## Boundaries this summary does not restate${preamble}`,
807			'fleet-batch summary record',
808		);
809	}
810	
811	export type BatchResult = Readonly<{
812		summary: FleetSummary;
813		markdown: string;
814		summaryPath: string;
815		markdownPath: string;
816		exitCode: number;
817	}>;
818	
819	/**
820	 * The fleet loop itself: serial, filing as it goes, summarising at the end.
821	 */
822	export async function runFleetBatch(
823		declarations: BatchDeclarations,
824		hooks: Readonly<{
825			runHarness: HarnessRunner;
826			publish?: PublishExecutor;
827			distStale?: () => Promise<boolean>;
828			cliEntry: string;
829		}>,
830	): Promise<BatchResult> {
831		const startedAt = new Date().toISOString();
832		const started = Date.now();
833		const rows: BatchRow[] = [];
834		for (const application of declarations.applications)
835			rows.push(await runOneApplication(application, declarations, hooks.runHarness));
836		const totals = tallyTotals(rows);
837		let steps: readonly PublishStepOutcome[] = Object.freeze([]);
838		if (declarations.publish) {
839			const stale = await (hooks.distStale ?? (() => distIsStale(declarations.root)))();
840			steps = await runPublishChain(
841				publishStepsFor({
842					distStale: stale,
843					trustDir: 'evidence/trust/current',
844					cliEntry: hooks.cliEntry,
845				}),
846				hooks.publish ?? spawnPublishStep(declarations.root),
847			);
848		}
849		const machineTimeMs = Date.now() - started;
850		const summary: FleetSummary = Object.freeze({
851			schemaVersion: FLEET_BATCH_SCHEMA,
852			flow: 'batch' as const,
853			name: declarations.name,
854			startedAt,
855			endedAt: new Date().toISOString(),
856			machineTimeMs,
857			declared: Object.freeze({
858				applicationsFrom: Object.freeze([...declarations.appsSource]),
859				laneRoot: displayPath(declarations.laneRoot),
860				forwarded: Object.freeze([...declarations.forwarded]),
861				concurrency:
862					'one application at a time, in the order declared; nothing in this batch ran in parallel',
863				publish: declarations.publish ? 'declared' : 'not-declared',
864			}),
865			totals,
866			unattended: unattendedStatement(totals),
867			applications: Object.freeze(rows),
868			publish: Object.freeze({ declared: declarations.publish, steps }),
869			notEstablished: FLEET_NOT_ESTABLISHED,
870		});
871		const markdown = renderFleetSummary(summary);
872		assertFleetSummaryHonesty(summary, markdown);
873		const directory = path.join(FLEET_BATCH_ROOT, declarations.name);
874		const summaryPath = path.join(directory, FLEET_SUMMARY_JSON);
875		const markdownPath = path.join(directory, FLEET_SUMMARY_MARKDOWN);
876		await writeRecord(summaryPath, summary);
877		await writeMarkdown(markdownPath, markdown);
878		const publishFailed = steps.some((step) => step.status !== 'ran' && step.status !== 'skipped');
879		return Object.freeze({
880			summary,
881			markdown,
882			summaryPath,
883			markdownPath,
884			exitCode: totals.defects > 0 || publishFailed ? 1 : 0,
885		});
886	}
887	
888	async function writeMarkdown(file: string, body: string): Promise<void> {
889		await mkdir(path.dirname(path.resolve(file)), { recursive: true });
890		await writeFile(path.resolve(file), body);
891	}
892	
893	/** The batch as an operator reads it: the rows, the totals, then what they name. */
894	export function renderBatch(result: BatchResult): string {
895		const lines = [
896			`fleet batch: ${result.summary.name}`,
897			`applications: ${String(result.summary.totals.applications)}`,
898			'',
899		];
900		for (const row of result.summary.applications)
901			lines.push(
902				`  - ${row.id}: ${row.terminalClassification}, interventions ${row.interventionCount === null ? 'not asserted' : String(row.interventionCount)}, ${String(row.elapsedMs)} ms`,
903			);
904		lines.push('');
905		lines.push(`proven: ${String(result.summary.totals.proven)}`);
906		lines.push(`refused: ${String(result.summary.totals.refused)}`);
907		for (const code of Object.keys(result.summary.totals.refusedByCode).sort())
908			lines.push(`  ${code}: ${String(result.summary.totals.refusedByCode[code])}`);
909		lines.push(`defects: ${String(result.summary.totals.defects)}`);
910		lines.push(`intervention count, summed: ${String(result.summary.totals.interventionCount)}`);
911		lines.push('');
912		lines.push(result.summary.unattended.statement);
913		lines.push('');
914		lines.push(`publish: ${result.summary.declared.publish}`);
915		for (const step of result.summary.publish.steps)
916			lines.push(
917				`  ${step.step}: ${step.status} (exit ${step.exitCode === null ? 'not-recorded' : String(step.exitCode)})`,
918			);
919		lines.push('');
920		lines.push(`summary: ${result.summaryPath}`);
921		lines.push(`document: ${result.markdownPath}`);
922		return `${lines.join('\n')}\n`;
923	}
924	
925	/** The batch name, when none was declared: the instant it started, as a path segment. */
926	export function defaultBatchName(now: Date = new Date()): string {
927		return now.toISOString().replace(/[:.]/g, '-');
928	}
929

